#!/bin/bash
set -euo pipefail
exec > >(tee -a /tmp/oneesan_bench.log) 2>&1
echo '=== ONEESAN RTX5090 BENCH START ==='
date -Is
nvidia-smi --query-gpu=name,memory.total,driver_version,pstate,power.limit,pci.bus_id --format=csv,noheader
nvcc --version | tail -n 2
mkdir -p /workspace/oneesan
cd /workspace/oneesan
printf '%s' '' | base64 -d | gzip -d > solver.cu
run_case() {
  n="$1"; target="$2"; W=$((n+1))
  echo "=== BUILD n=$n W=$W target=${target}MiB ==="
  nvcc -O3 -std=c++17 -arch=sm_120 -DTARGET_W="$W" solver.cu -o "solver_n${n}"
  echo "=== RUN n=$n ==="
  ./"solver_n${n}" "$n" 4294967291 "$target" 14 1
  echo "=== DONE n=$n ==="
}
run_case 18 4096
run_case 20 4096
run_case 21 4096
run_case 22 4096
echo '=== ONEESAN RTX5090 BENCH COMPLETE ==='
date -Is
